package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.view.View;
import android.widget.*;
import org.json.*;
import java.util.*;
final class ItemEditorDialog {
 private boolean saving,uploading;
 ItemEditorDialog(Context c,JSONObject item,boolean media,TitleDetailsDialog.Change changed,Runnable dismissed){NativeSheet s=new NativeSheet(c,media?"🍿 Editar título":"🎮 Editar jogo");s.dialog.setOnDismissListener(d->dismissed.run());final long[] selectedSteam={item.optLong("steam_appid")};Map<String,EditText> text=new LinkedHashMap<>();List<View> controls=new ArrayList<>();
  ImageView preview=new ImageView(c);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);s.body.addView(preview,new LinearLayout.LayoutParams(-1,NativeSheet.dp(c,150)));AccountImageLoader.load(preview,value(item,"capa",""),media?"":value(item,"steam_appid",""));EditText cover=field(c,s,"Capa • URL do catálogo",value(item,"capa",""),2000);text.put("capa",cover);Button pick=button(c,"🖼 Escolher imagem do celular",false);s.body.addView(pick);controls.add(pick);Button show=button(c,"Ver prévia da capa",false);s.body.addView(show);show.setOnClickListener(v->AccountImageLoader.load(preview,cover.getText().toString().trim()));controls.add(show);
  text.put("nome",field(c,s,"Nome do título",value(item,"nome",""),160));Spinner status=choice(c,s,"Status",media?ItemEditInput.MEDIA_STATUS:ItemEditInput.GAME_STATUS,value(item,"status",""));Spinner rating=choice(c,s,"Sua avaliação",ItemEditInput.RATINGS,value(item,"nota","Sem avaliação"));controls.add(status);controls.add(rating);
  MultiChoiceField platform=new MultiChoiceField(c,"Plataformas",new String[]{"💻 PC","🎮 PlayStation 5","🎮 PlayStation 4","🟩 Xbox Series","🟩 Xbox One","🕹️ Switch","🎮 Steam Deck","📱 Mobile","👾 Retro","🥽 VR"},value(item,"plataforma",""),", ",120);
  Spinner priority=choice(c,null,"Prioridade",new String[]{"Não informado","🔴 Alta","🟡 Média","🟢 Baixa"},value(item,"prioridade",""));Spinner kind=choice(c,null,"Tipo",MediaInput.TYPES,value(item,"tipo",MediaInput.TYPES[0]));MultiChoiceField services=new MultiChoiceField(c,"Onde assistir",new String[]{"🔴 Netflix","🟣 Max","🟠 Crunchyroll","🔵 Prime Video","⚫ Disney+","🍎 Apple TV+","🔵 Paramount+","▶ YouTube","🎞 Cinema","Outro"},value(item,"onde","")," • ",80);
  if(media){label(c,s,"Tipo");s.body.addView(kind);label(c,s,"Onde assistir");s.body.addView(services);text.put("duracao",field(c,s,"Duração / temporadas / episódios",value(item,"duracao",""),80));controls.add(kind);controls.add(services);}else{label(c,s,"Plataformas");s.body.addView(platform);label(c,s,"Prioridade");s.body.addView(priority);controls.add(platform);controls.add(priority);for(String[] spec:new String[][]{{"horas","Horas jogadas"},{"tempo_est","Tempo para zerar (h)"},{"conquistas","Conquistas (%)"}}){EditText e=field(c,s,spec[1],value(item,spec[0],""),12);e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);text.put(spec[0],e);}}
  EditText year=field(c,s,"Ano de lançamento",value(item,"ano",""),4);year.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);text.put("ano",year);Object raw=item.opt("generos");String genres=raw instanceof JSONArray?jsonGenres((JSONArray)raw):value(item,"generos","");MultiChoiceField genre=new MultiChoiceField(c,"Gêneros",media?new String[]{"🎭 Drama","😂 Comédia","⚔️ Ação","👻 Terror","🚀 Ficção Científica","🐉 Fantasia","🎨 Animação","🍥 Anime","🔍 Suspense","💕 Romance","🗺 Aventura","📚 Documentário"}:new String[]{"⚔️ Ação","🗡️ Ação-Aventura","📜 RPG","🌍 Mundo Aberto","🔫 Tiro","👻 Terror","🕹️ Plataforma","🗺️ Metroidvania","🔄 Roguelike","🧩 Puzzle","🏎 Corrida","⚽ Esporte","♟ Estratégia","🧪 Simulação","🤝 Cooperativo","📖 Visual Novel"},genres,", ",500);label(c,s,"Gêneros");s.body.addView(genre);controls.add(genre);
  if(!media){Button gridCovers=button(c,"Escolher capa no SteamGridDB",false);s.body.addView(gridCovers);controls.add(gridCovers);gridCovers.setOnClickListener(v->{try{JSONObject query=new JSONObject(item.toString()).put("nome",text.get("nome").getText().toString().trim());if(selectedSteam[0]>0)query.put("steam_appid",selectedSteam[0]);GameCoverPickerDialog.show(c,query,url->{cover.setText(url);AccountImageLoader.load(preview,url);Toast.makeText(c,"Capa selecionada. Salve para aplicar.",Toast.LENGTH_LONG).show();});}catch(JSONException e){Toast.makeText(c,"Não foi possível abrir a busca de capas.",Toast.LENGTH_LONG).show();}});EditText appId=field(c,s,"Steam App ID (opcional)",value(item,"steam_appid",""),10);appId.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);text.put("steam_appid",appId);controls.add(appId);Button steamData=button(c,"Associar App ID pelo IGDB",false);s.body.addView(steamData);steamData.setOnClickListener(v->{steamData.setEnabled(false);new AccountRepository(c).steamLookup(text.get("nome").getText().toString(),(rows,error)->{steamData.setEnabled(true);if(error!=null){Toast.makeText(c,error,Toast.LENGTH_LONG).show();return;}JSONObject game=rows.optJSONObject(0);selectedSteam[0]=game.optLong("steamAppid");appId.setText(String.valueOf(selectedSteam[0]));Toast.makeText(c,"App ID associado pelo vínculo do IGDB. Confira antes de salvar.",Toast.LENGTH_LONG).show();});});}

  for(String key:new String[]{"inicio","data"}){EditText e=field(c,s,key.equals("inicio")?"Data de início":media?"Assistido em":"Finalizado em",value(item,key,""),10);text.put(key,e);e.setFocusable(false);e.setOnClickListener(v->{Calendar cal=Calendar.getInstance();String rawDate=e.getText().toString();if(rawDate.matches("[12][0-9]{3}-[0-9]{2}-[0-9]{2}"))cal.set(Integer.parseInt(rawDate.substring(0,4)),Integer.parseInt(rawDate.substring(5,7))-1,Integer.parseInt(rawDate.substring(8,10)));new android.app.DatePickerDialog(c,(picker,y,m,day)->e.setText(String.format(Locale.ROOT,"%04d-%02d-%02d",y,m+1,day)),cal.get(Calendar.YEAR),cal.get(Calendar.MONTH),cal.get(Calendar.DAY_OF_MONTH)).show();});e.setOnLongClickListener(v->{e.setText("");return true;});}
  EditText review=field(c,s,"Sua avaliação / anotações",value(item,"review",""),4000);review.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);review.setMinLines(3);text.put("review",review);controls.addAll(text.values());TextView state=NativeSheet.text(c,"",13,0xffb7a6ff);s.body.addView(state);s.footer.setVisibility(View.VISIBLE);Button save=button(c,"Salvar alterações",true);s.footer.addView(save);AccountRepository repo=new AccountRepository(c);
  pick.setOnClickListener(v->{if(saving||uploading)return;((MainActivity)c).chooseStickerImage(uri->{if(!s.dialog.isShowing())return;uploading=true;s.busy(true);pick.setEnabled(false);save.setEnabled(false);state.setText("Enviando e verificando a capa…");repo.uploadItemCover(item,media,uri,(rows,error)->{uploading=false;s.busy(false);if(!s.dialog.isShowing())return;pick.setEnabled(true);save.setEnabled(true);if(error!=null){state.setText(error);return;}String url=rows.optJSONObject(0).optString("url");cover.setText(url);AccountImageLoader.load(preview,url);state.setText("Capa aprovada. Salve as alterações para aplicar.");});});});
  save.setOnClickListener(v->{if(saving||uploading)return;try{JSONObject draft=new JSONObject();if(!media&&selectedSteam[0]>0)draft.put("steam_appid",selectedSteam[0]);for(Map.Entry<String,EditText> entry:text.entrySet())draft.put(entry.getKey(),entry.getValue().getText().toString().trim());draft.put("status",status.getSelectedItem()).put("nota","Sem avaliação".equals(rating.getSelectedItem())?"":rating.getSelectedItem()).put("generos",genre.value());if(media)draft.put("tipo",kind.getSelectedItem()).put("onde",services.value());else draft.put("plataforma",platform.value()).put("prioridade",empty(priority));CatalogDraftInput.validate(draft.optString("nome"),draft.optString("ano"),draft.optString("generos"),draft.optString("inicio"),draft.optString("data"),draft.optString("review"));ItemInfoInput.validate(draft.optString("nome"),draft.optString("plataforma"),draft.optString("loja"),draft.optString("ano"),draft.optString("prioridade"),draft.optString("tempo_est"),draft.optString("conquistas"),draft.optString("generos"),draft.optString("preco"));if(!media)for(String key:new String[]{"horas","tempo_est"})if(!draft.optString(key).isEmpty())GameInput.hours(draft.optString(key));if(!CoverEditPolicy.allowed(draft.optString("capa"),value(item,"capa",""),SessionPreferences.get(c).getString("user_id",""),BuildConfig.SUPABASE_URL))throw new IllegalArgumentException("Escolha uma imagem do celular ou uma capa do catálogo permitido.");saving=true;s.busy(true);for(View control:controls)control.setEnabled(false);save.setEnabled(false);state.setText("Salvando…");repo.updateLibraryItem(item,media,draft,(rows,error)->{saving=false;s.busy(false);if(!s.dialog.isShowing())return;if(error!=null){state.setText(error+" Feche e atualize antes de reenviar.");return;}s.dialog.dismiss();changed.done(rows.optJSONObject(0),false);});}catch(Exception e){state.setText(e.getMessage());}});s.show();
 }
 private static String empty(Spinner s){return "Não informado".equals(s.getSelectedItem())?"":s.getSelectedItem().toString();}
 private static String jsonGenres(JSONArray a){List<String> names=new ArrayList<>();for(int i=0;i<a.length();i++)names.add(a.optString(i));return android.text.TextUtils.join(", ",names);}
 private static String value(JSONObject item,String key,String fallback){return item.isNull(key)?fallback:item.optString(key,fallback);}
 private static void label(Context c,NativeSheet s,String value){s.body.addView(NativeSheet.text(c,value,12,0xffbba7df));}
 private static EditText field(Context c,NativeSheet s,String label,String current,int max){label(c,s,label);EditText e=NativeSheet.input(c,label,max);e.setText(current);s.body.addView(e);return e;}
 private static Spinner choice(Context c,NativeSheet s,String label,String[] choices,String current){String[] values=ItemEditInput.preserve(choices,current);Spinner spinner=NativeSheet.options(c,values);for(int i=0;i<values.length;i++)if(values[i].equals(current))spinner.setSelection(i);if(s!=null){label(c,s,label);s.body.addView(spinner);}return spinner;}
 private static Button button(Context c,String label,boolean primary){Button b=new Button(c);b.setText(label);AppStyle.button(b,primary);return b;}
}
